# v15.55: Theme 1 (white page, blue summary card, calmer Simple Home) and Legacy Theme switch
from playwright.sync_api import sync_playwright
CSV='/home/claude/Transactions.csv'
def ok(n,c): print(('PASS ' if c else 'FAIL ')+n)
def boot(b,scheme):
    ctx=b.new_context(viewport={'width':390,'height':844},service_workers='block',color_scheme=scheme); pg=ctx.new_page(); pg.errs=[]; pg.on('pageerror',lambda e:pg.errs.append(str(e)))
    pg.goto('http://localhost:8123/'); pg.wait_for_selector('#first-file',state='attached'); pg.set_input_files('#first-file',CSV); pg.wait_for_selector('#setup',timeout=20000); pg.click('#setup .btn'); pg.wait_for_timeout(2500); return pg
MODE=lambda pg,m: pg.evaluate("(async()=>{const c=await import('/js/core.js');c.commit(d=>{d.settings.mode='%s'})})()"%m)
BG=lambda pg: pg.evaluate("getComputedStyle(document.body).backgroundColor")
with sync_playwright() as p:
    b=p.chromium.launch(); pg=boot(b,'light')
    pg.goto('http://localhost:8123/#/home'); MODE(pg,'advanced'); pg.wait_for_timeout(1200)
    ok('Theme 1 is the default', pg.evaluate("document.documentElement.dataset.design")=='theme1')
    ok('light page is pure white (Advanced) '+BG(pg), BG(pg)=='rgb(255, 255, 255)')
    c=pg.evaluate("(()=>{const s=document.querySelector('.sumcard');if(!s)return null;const r=e=>e.getBoundingClientRect();const n=s.querySelector('.sc-net b'),i=s.querySelectorAll('.sc-row');return {bg:getComputedStyle(s.querySelector('.sc-front')).backgroundImage.slice(0,15),netpx:parseFloat(getComputedStyle(n).fontSize),rowpx:parseFloat(getComputedStyle(i[0].querySelector('b')).fontSize),txt:s.innerText.replace(/\\s+/g,' '),y:[r(n).top,r(i[0]).top,r(i[1]).top],arrows:[i[0].querySelector('.sc-arr').textContent,i[1].querySelector('.sc-arr').textContent],flows:[...s.querySelectorAll('[data-act=flow]')].map(x=>x.dataset.k)}})()")
    ok('summary card has a gradient %s'%[c and c['bg']], c and c['bg'].startswith('linear-gradient'))
    ok('net income is larger than the rows %s'%[c and (c['netpx'],c['rowpx'])], c and c['netpx']>=c['rowpx']*1.4)
    ok('order: Net income, then Income, then Expense', c and c['y'][0]<c['y'][1] and abs(c['y'][1]-c['y'][2])<2 and c['txt'].index('Net income')<c['txt'].index('Income')<c['txt'].index('Expense'))
    ok('Income has a down arrow, Expense an up arrow', c and c['arrows']==['↓','↑'])
    ok('the three amounts still open the flow sheets', c and sorted(c['flows'])==['inflow','net','outflow'])
    pg.evaluate("document.querySelector('.sumcard [data-k=inflow]').click()"); pg.wait_for_timeout(500); ok('tapping Income opens its sheet', pg.locator('.sheet').count()>=1); pg.keyboard.press('Escape'); pg.wait_for_timeout(300)
    MODE(pg,'simple'); pg.wait_for_timeout(1200)
    ok('light page is pure white (Simple) '+BG(pg), BG(pg)=='rgb(255, 255, 255)')
    ok('Simple Home keeps the extras behind one More fold', pg.locator('.homemore').count()==1 and not pg.evaluate("document.querySelector('.homemore').open"))
    n_simple=pg.locator('#view section, main section').count()
    pg.goto('http://localhost:8123/#/settings'); pg.wait_for_timeout(800)
    t=pg.evaluate("document.body.textContent"); ok('Settings offers Theme 1 and Legacy Theme', 'Theme 1' in t and 'Legacy Theme' in t)
    pg.evaluate("document.querySelector('[data-act=look][data-k=design][data-v=legacy]').click()"); pg.wait_for_timeout(600)
    ok('switching to Legacy Theme sets it', pg.evaluate("document.documentElement.dataset.design")=='legacy' and BG(pg)!='rgb(255, 255, 255)')
    pg.goto('http://localhost:8123/#/home'); pg.wait_for_timeout(1200)
    ok('Legacy Home has the old strip and no fold', pg.locator('.sumcard').count()==0 and pg.locator('.homemore').count()==0 and 'Cash inflow' in pg.inner_text('.strip'))
    MODE(pg,'advanced'); pg.wait_for_timeout(800); ok('Legacy Advanced keeps its blue-grey page '+BG(pg), BG(pg)=='rgb(212, 219, 230)')
    pg.goto('http://localhost:8123/#/settings'); pg.wait_for_timeout(600); pg.evaluate("document.querySelector('[data-act=look][data-k=design][data-v=theme1]').click()"); pg.wait_for_timeout(500)
    ok('and back to Theme 1', pg.evaluate("document.documentElement.dataset.design")=='theme1' and BG(pg)=='rgb(255, 255, 255)')
    ok('no page errors %s'%pg.errs, not pg.errs)
    pd=boot(b,'dark'); pd.goto('http://localhost:8123/#/home'); pd.wait_for_timeout(1200)
    ok('dark mode is untouched '+BG(pd), BG(pd) in ('rgb(14, 20, 26)','rgb(7, 11, 16)'))
